/**
 * Reviewed extraction snapshot for FIC sanction documents that are scanned
 * images (no PDF text layer): all 2017-2021 notices and some later ones.
 * Values were produced by OCR (three independent passes; a field is kept only
 * when at least two passes agree or the document's own payable + suspended
 * figures reconcile) and are keyed by the immutable document URL. Anything
 * the passes could not agree on is left null rather than guessed.
 * Documents NOT listed here are parsed live from their PDF text layer.
 */
export interface FicScannedExtraction {
  confidence: "ocr-agree" | "ocr-majority" | "ocr-reconciled" | "unresolved";
  amount: number | null;
  suspendedAmount: number | null;
  reducedAmount: number | null;
  signedDate: string | null;
  signedMonth: string | null;
  actions: string[];
  provisions: string[];
  /** Set when a figure was reconciled by a rule and should be checked by a person. */
  review: string | null;
}

